CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS admins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name_en text NOT NULL,name_ar text NOT NULL,slug text UNIQUE NOT NULL,description_en text DEFAULT '',description_ar text DEFAULT '',image_url text,position int DEFAULT 0,active boolean DEFAULT true,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name_en text NOT NULL,name_ar text NOT NULL,slug text UNIQUE NOT NULL,description_en text DEFAULT '',description_ar text DEFAULT '',price numeric(12,2) NOT NULL CHECK(price>=0),discount_type text CHECK(discount_type IN ('none','percent','fixed')) DEFAULT 'none',discount_value numeric(12,2) DEFAULT 0,category_id uuid REFERENCES categories(id) ON DELETE SET NULL,stock int NOT NULL DEFAULT 0,low_stock_threshold int DEFAULT 5,tags text[] DEFAULT '{}',ingredients_en text DEFAULT '',ingredients_ar text DEFAULT '',usage_en text DEFAULT '',usage_ar text DEFAULT '',featured boolean DEFAULT false,bestseller boolean DEFAULT false,new_arrival boolean DEFAULT false,active boolean DEFAULT true,specifications jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS product_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid REFERENCES products(id) ON DELETE CASCADE,url text NOT NULL,alt_en text DEFAULT '',alt_ar text DEFAULT '',position int DEFAULT 0);
CREATE TABLE IF NOT EXISTS offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title_en text NOT NULL,title_ar text NOT NULL,type text NOT NULL CHECK(type IN('percentage','fixed','bundle','buy_x_get_y')),value numeric(12,2) DEFAULT 0,bundle_price numeric(12,2),buy_x int,buy_y int,start_date timestamptz,end_date timestamptz,active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS offer_items(offer_id uuid REFERENCES offers(id) ON DELETE CASCADE,product_id uuid REFERENCES products(id) ON DELETE CASCADE,quantity int DEFAULT 1,PRIMARY KEY(offer_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_number text UNIQUE NOT NULL,customer_name text NOT NULL,phone1 text NOT NULL,phone2 text NOT NULL,governorate text NOT NULL,address text NOT NULL,building_number text,apartment_number text,subtotal numeric(12,2) NOT NULL,discount numeric(12,2) NOT NULL,savings numeric(12,2) NOT NULL,total numeric(12,2) NOT NULL,status text DEFAULT 'new' CHECK(status IN('new','confirmed','preparing','shipped','delivered','cancelled')),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES orders(id) ON DELETE CASCADE,product_id uuid REFERENCES products(id) ON DELETE SET NULL,product_name_snapshot text NOT NULL,price_snapshot numeric(12,2) NOT NULL,quantity int NOT NULL,discount_snapshot numeric(12,2) DEFAULT 0,total numeric(12,2) NOT NULL,selected_specification text DEFAULT '');
CREATE TABLE IF NOT EXISTS site_settings(key text PRIMARY KEY,value text NOT NULL,updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS homepage_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),type text NOT NULL,title_en text,title_ar text,subtitle_en text,subtitle_ar text,image_url text,position int DEFAULT 0,active boolean DEFAULT true,product_ids uuid[] DEFAULT '{}',category_id uuid REFERENCES categories(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS products_search_idx ON products USING gin(to_tsvector('simple',name_en||' '||description_en));
ALTER TABLE products ADD COLUMN IF NOT EXISTS specifications jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE order_items ADD COLUMN IF NOT EXISTS selected_specification text DEFAULT '';
